16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.Email;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Digits(fraction = 0, integer = 10)
51	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    @Email
56	    private String email;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "membership_number")
62	    private Integer membershipNumber;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "membership_tier")
68	    private String membershipTier;
69	
70	    @Column(name = "namesake_count")
71	    private Integer namesakeCount;
72	
73	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
74	    private Set<Pet> pets;
75	
76	    public String getAddress() {
77	        return this.address;
78	    }
79	
80	    public void setAddress(String address) {
81	        this.address = address;
82	    }
83	
84	    public String getCity() {
85	        return this.city;
86	    }
87	
88	    public void setCity(String city) {
89	        this.city = city;
90	    }
91	
92	    public String getTelephone() {
93	        return this.telephone;
94	    }
95	
96	    public void setTelephone(String telephone) {
97	        // Store telephone numbers as digits only, stripping spaces, dashes and
98	        // parentheses so that formatted input such as "(613) 555-0100" is kept
99	        // and compared as "6135550100".
100	        this.telephone = telephone == null ? null : telephone.replaceAll("[\\s()-]", "");
101	    }
102	
103	    public String getEmail() {
104	        return this.email;
105	    }
106	
107	    public void setEmail(String email) {
108	        this.email = email;
109	    }
110	
111	    public LocalDate getRegistrationDate() {
112	        return this.registrationDate;
113	    }
114	
115	    public void setRegistrationDate(LocalDate registrationDate) {
116	        this.registrationDate = registrationDate;
117	    }
118	
119	    public Integer getMembershipNumber() {
120	        return this.membershipNumber;
121	    }
122	
123	    public void setMembershipNumber(Integer membershipNumber) {
124	        this.membershipNumber = membershipNumber;
125	    }
126	
127	    public String getCustomerCode() {
128	        return this.customerCode;
129	    }
130	
131	    public void setCustomerCode(String customerCode) {
132	        this.customerCode = customerCode;
133	    }
134	
135	    public String getMembershipTier() {
136	        return this.membershipTier;
137	    }
138	
139	    public void setMembershipTier(String membershipTier) {
140	        this.membershipTier = membershipTier;
141	    }
142	
143	    public Integer getNamesakeCount() {
144	        return this.namesakeCount;
145	    }
146	
147	    public void setNamesakeCount(Integer namesakeCount) {
148	        this.namesakeCount = namesakeCount;
149	    }
150	
151	    protected Set<Pet> getPetsInternal() {
152	        if (this.pets == null) {
153	            this.pets = new HashSet<>();
154	        }
155	        return this.pets;
156	    }
157	
158	    protected void setPetsInternal(Set<Pet> pets) {
159	        this.pets = pets;
160	    }
161	
162	    public List<Pet> getPets() {
163	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
164	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
165	        return Collections.unmodifiableList(sortedPets);
166	    }
167	
168	    public void setPets(List<Pet> pets) {
169	        this.pets = new HashSet<>(pets);
170	    }
171	
172	    public void addPet(Pet pet) {
173	        getPetsInternal().add(pet);
174	        pet.setOwner(this);
175	    }
176	
177	    /**
178	     * Return the Pet with the given name, or null if none found for this Owner.
179	     *
180	     * @param name to test
181	     * @return true if pet name is already in use
182	     */
183	    public Pet getPet(String name) {
184	        return getPet(name, false);
185	    }
186	
187	    /**
188	     * Return the Pet with the given name, or null if none found for this Owner.
189	     *
190	     * @param name to test
191	     * @return true if pet name is already in use
192	     */
193	    public Pet getPet(String name, boolean ignoreNew) {
194	        name = name.toLowerCase();
195	        for (Pet pet : getPetsInternal()) {
196	            if (!ignoreNew || !pet.isNew()) {
197	                String compName = pet.getName();
198	                compName = compName.toLowerCase();
199	                if (compName.equals(name)) {
200	                    return pet;
201	                }
202	            }
203	        }
204	        return null;
205	    }
206	
207	    public Pet getPet(Integer petId) {
208	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
209	    }
210	
211	    @Override
212	    public String toString() {
213	        return new ToStringCreator(this)
214	
215	            .append("id", this.getId())
216	            .append("new", this.isNew())
217	            .append("lastName", this.getLastName())
218	            .append("firstName", this.getFirstName())
219	            .append("address", this.address)
220	            .append("city", this.city)
221	            .append("telephone", this.telephone)
222	            .toString();
223	    }
224	}
